{"path": "islands/01-recurrence/scratch/verify_recursion.py", "content": """"Reproduce and stress-test the C0024 recursion (corrected Zeilberger bound).

Independent re-derivation (not a copy of any prior script, which is gitignored
and absent). Uses the validated solver's table for f(q,r), reconstructs
B_c(a) = f(c+a,c)-(c+a) for all c <= RMAX, a <= AMAX, and checks:

  F1  translation B_r(a)=f(r+a,r)-(r+a) matches census d-values
  F2  B_r is p_r-periodic for a >= u_r and not for a = u_r-1 (live rows)
  F3  Fundamental Recurrence L_a = mex(W_r(a) U {L_{a-1}-1,...,L_0-a})
      reproduces B_r for every row, live AND stale
  F4  W_r is q_r-periodic for a >= t_r
  F5  the three inequalities (ii),(iii) and the stale-row bound
  F6  *Lemma Bounded*: max B_r(a) <= m_r = 1 + max{B_c(a): c<r}  (the step
      that lets the finite memory M=m_r bound the row-r values)
  F7  the finite-memory mex (M=m_r trailing values) reproduces B_r
"""
from __future__ import annotations
import sys
from math import gcd
sys.path.insert(0, ".")
from GROUND_TRUTH import chomp

RMAX = 400
AMAX = 1400
QMAX = RMAX + AMAX

def lcm(a, b):
    return a * b // gcd(a, b) if a and b else max(a, b)

print(f"[load] table rmax={RMAX} qmax={QMAX}")
T = chomp.table(RMAX, QMAX)          # T[q][r] = f(q,r); r>q gives f(q,q)
print(f"[load] census rmax={RMAX}")
cen = chomp.census(RMAX, alpha=6.0, margin=600)

# B[r][a] = f(r+a,r)-(r+a) for a in 0..AMAX, or None if f<q (not a loser).
B = {}
for r in range(RMAX + 1):
    row = []
    for a in range(AMAX + 1):
        q = r + a
        if q > QMAX:
            row.append(None)
            continue
        d = T[q][r] - q
        row.append(d if d >= 0 else None)   # None = no genuine P-position
    B[r] = row

# ---- F1: translation matches census (periodic tail) ---------------------
print("[F1] translation vs census d-values")
bad = 0
for r in range(1, RMAX + 1):
    c = cen[r]
    p, N = c["period"], c["N"]
    if c["cls"] == "stale":
        # B_r(a) defined exactly for a <= u_r-1 with last value 0
        u = N - r
        for a in range(AMAX + 1):
            want = None
            if a <= u - 1:
                want = 0 if a == u - 1 else None  # only last is guaranteed 0
            # we can only check the last value is 0 and beyond is None
        for a in range(u, AMAX + 1):
            if B[r][a] is not None:
                bad += 1
                if bad <= 5:
                    print(f"  r={r} a={a}: stale but B={B[r][a]} (want None)")
    else:
        u = N - r
        for a in range(u, AMAX + 1):
            want = c["dvals"][(a - u) % p]
            if B[r][a] != want:
                bad += 1
                if bad <= 5:
                    print(f"  r={r} a={a}: B={B[r][a]} census={want}")
print(f"  {'OK' if bad==0 else 'FAIL'} ({bad} mismatches)")

# ---- F2: periodicity ----------------------------------------------------
print("[F2] periodicity from u_r (live rows)")
bad = 0
for r in range(1, RMAX + 1):
    c = cen[r]
    if c["cls"] == "stale":
        continue
    p, u = c["period"], c["N"] - r
    for a in range(u, AMAX + 1 - p):
        if B[r][a] != B[r][a + p]:
            bad += 1
            if bad <= 5:
                print(f"  r={r}: B[{a}]={B[r][a]} != B[{a+p}]={B[r][a+p]}")
    # not periodic at u-1 when u>=1
    if u >= 1 and u - 1 + p <= AMAX:
        if B[r][u - 1] == B[r][u - 1 + p]:
            bad += 1
            if bad <= 5:
                print(f"  r={r}: prematurely periodic at a={u-1}")
print(f"  {'OK' if bad==0 else 'FAIL'} ({bad} mismatches)")

# ---- F3: Fundamental Recurrence -----------------------------------------
# W_r(a) = union over c<r of {B_c(a+r-c)} and {B_c(0)-(r-c)-a, if >=0}
def W(r, a):
    s = set()
    for c in range(r):
        a2 = a + r - c
        if a2 <= AMAX and B[c][a2] is not None:
            s.add(B[c][a2])
        v = (B[c][0] if B[c][0] is not None else 0) - (r - c) - a
        if v >= 0:
            s.add(v)
    return s

def mex(S):
    m = 0
    while m in S:
        m += 1
    return m

print("[F3] Fundamental Recurrence reproduces B_r (live + stale)")
bad = 0
for r in range(1, RMAX + 1):
    L = [B[r][a] for a in range(AMAX + 1)]
    for a in range(1, AMAX + 1):
        if L[a] is None:
            continue
        tail = {L[a - i] - i for i in range(1, a + 1) if L[a - i] is not None and L[a - i] - i >= 0}
        want = mex(W(r, a) | tail)
        if want != L[a]:
            bad += 1
            if bad <= 5:
                print(f"  r={r} a={a}: recurrence={want} true B={L[a]}")
print(f"  {'OK' if bad==0 else 'FAIL'} ({bad} mismatches)")

# ---- F4: W_r periodicity ------------------------------------------------
print("[F4] W_r is q_r-periodic for a >= t_r")
bad = 0
for r in range(1, RMAX + 1):
    q_r = 1
    for c in range(r):
        q_r = lcm(q_r, cen[c]["period"] if cen[c]["cls"] == "live" else 1)
    U_r = max(cen[c]["N"] - c for c in range(r)) if r > 0 else 0
    t_r = max(U_r, r)
    for a in range(t_r, AMAX + 1 - q_r):
        if W(r, a) != W(r, a + q_r):
            bad += 1
            if bad <= 5:
                print(f"  r={r} a={a}: W not {q_r}-periodic")
print(f"  {'OK' if bad==0 else 'FAIL'} ({bad} mismatches)")

# ---- F5 + F6 + F7 -------------------------------------------------------
print("[F5/F6/F7] inequalities, Lemma Bounded, finite-memory mex")
bad = 0
worst_p = worst_u = 0.0
for r in range(1, RMAX + 1):
    c = cen[r]
    p_r = c["period"] if c["cls"] == "live" else 1
    u_r = c["N"] - r
    q_r = 1
    for cc in range(r):
        q_r = lcm(q_r, cen[cc]["period"] if cen[cc]["cls"] == "live" else 1)
    U_r = max(cen[cc]["N"] - cc for cc in range(r)) if r > 0 else 0
    m_r = 1 + max((B[cc][a] for cc in range(r) for a in range(AMAX + 1)
                   if B[cc][a] is not None), default=0)
    t_r = max(U_r, r)
    bound_p = q_r * (m_r + 1) ** m_r
    bound_u = max(t_r, m_r) + q_r * (m_r + 1) ** m_r

    # F5
    if p_r > bound_p:
        bad += 1; print(f"  r={r}: p_r={p_r} > bound_p={bound_p}")
    if u_r > bound_u:
        bad += 1; print(f"  r={r}: u_r={u_r} > bound_u={bound_u}")
    worst_p = max(worst_p, p_r / bound_p)
    worst_u = max(worst_u, u_r / bound_u)

    # F6 Lemma Bounded: max B_r <= m_r
    maxBr = max((B[r][a] for a in range(AMAX + 1) if B[r][a] is not None), default=0)
    if maxBr > m_r:
        bad += 1
        if bad <= 10:
            print(f"  r={r}: Lemma Bounded FAILS: max B_r={maxBr} > m_r={m_r}")

    # F7 finite-memory mex with M=m_r trailing values reproduces B_r
    M = m_r
    L = B[r]
    for a in range(1, AMAX + 1):
        if L[a] is None:
            continue
        tail = {L[a - i] - i for i in range(1, M + 1) if a - i >= 0 and L[a - i] is not None and L[a - i] - i >= 0}
        want = mex(W(r, a) | tail)
        if want != L[a]:
            bad += 1
            if bad <= 10:
                print(f"  r={r} a={a}: finite-mem mex={want} true B={L[a]} (M={M})")

print(f"  {'OK' if bad==0 else 'FAIL'} ({bad} failures); worst p_r/bound={worst_p:.4f}, u_r/bound={worst_u:.4f}")
print("DONE")"}

